export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

interface Rejection {
  provider: Provider;
  reason: RefusalReason;
}

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

interface InvalidCommandBody {
  code: "invalid_command";
}

interface NotFoundBody {
  code: "not_found";
}

interface AbortBody {
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: Rejection[];
}

export interface ServiceResponse {
  status: number;
  body: PublicShipment | InvalidCommandBody | NotFoundBody | AbortBody;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierResult =
  | { kind: "confirmed"; provider: Provider; bookingId: string }
  | { kind: "refused"; rejection: Rejection }
  | { kind: "deferred"; provider: Provider; retryAtMs: number }
  | { kind: "aborted"; provider: Provider; classification: Exclude<AbortClassification, "repository_failure"> };

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRejection(value: unknown): value is Rejection {
  return isObject(value) && isProvider(value.provider) && isRefusalReason(value.reason);
}

function areRejections(value: unknown): value is Rejection[] {
  return Array.isArray(value) && value.every(isRejection);
}

function isFutureSafeInteger(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };

  if (shipment.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (shipment.state === "dispatched") {
    return {
      ...fields,
      state: "dispatched",
      provider: shipment.provider,
      bookingId: shipment.bookingId,
      dispatchedAtMs: shipment.dispatchedAtMs,
    };
  }
  if (shipment.state === "deferred") {
    return {
      ...fields,
      state: "deferred",
      nextProvider: shipment.nextProvider,
      retryAtMs: shipment.retryAtMs,
      rejections: shipment.rejections,
    };
  }
  return {
    ...fields,
    state: "unavailable",
    rejections: shipment.rejections,
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    typeof value.routeCode !== "string" ||
    typeof value.parcelGrams !== "number"
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1 as const,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    typeof value.dispatchedAtMs === "number"
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    areRejections(value.rejections)
  ) {
    return {
      ...fields,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections: cloneRejections(value.rejections),
    };
  }
  if (value.state === "unavailable" && areRejections(value.rejections)) {
    return {
      ...fields,
      state: "unavailable",
      rejections: cloneRejections(value.rejections),
    };
  }
  return undefined;
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function cloneRejections(rejections: Rejection[]): Rejection[] {
  return rejections.map((rejection) => ({
    provider: rejection.provider,
    reason: rejection.reason,
  }));
}

function hasRefusal(rejections: Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: cloneRejections(rejections),
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): ServiceResponse {
  const body = abortBody(shipmentId, failedAt, classification, rejections);
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: body.rejections,
  });
  return { status: 500, body };
}

function classifyAtlasRejection(value: unknown, nowMs: number): CarrierResult {
  if (!isObject(value) || typeof value.code !== "string") {
    return { kind: "aborted", provider: "atlas", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (isRefusalReason(value.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "atlas", reason: value.reason },
      };
    }
    return { kind: "aborted", provider: "atlas", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    if (isFutureSafeInteger(value.retryAtMs, nowMs)) {
      return { kind: "deferred", provider: "atlas", retryAtMs: value.retryAtMs };
    }
    return { kind: "aborted", provider: "atlas", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", provider: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): CarrierResult {
  if (!isObject(value) || typeof value.type !== "string") {
    return { kind: "aborted", provider: "beacon", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (isObject(value.details) && isRefusalReason(value.details.reason)) {
      return {
        kind: "refused",
        rejection: { provider: "beacon", reason: value.details.reason },
      };
    }
    return { kind: "aborted", provider: "beacon", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (isObject(value.details) && isFutureSafeInteger(value.details.retryAtMs, nowMs)) {
      return { kind: "deferred", provider: "beacon", retryAtMs: value.details.retryAtMs };
    }
    return { kind: "aborted", provider: "beacon", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", provider: "beacon", classification: "unknown_failure" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierResult> {
  if (provider === "atlas") {
    try {
      const confirmation = await dependencies.atlas.book(request);
      if (
        isObject(confirmation) &&
        typeof confirmation.bookingId === "string" &&
        confirmation.bookingId.length > 0
      ) {
        return { kind: "confirmed", provider, bookingId: confirmation.bookingId };
      }
      return { kind: "aborted", provider, classification: "invalid_provider_response" };
    } catch (error) {
      return classifyAtlasRejection(error, nowMs);
    }
  }

  try {
    const confirmation = await dependencies.beacon.reserve(request);
    if (
      isObject(confirmation) &&
      typeof confirmation.reference === "string" &&
      confirmation.reference.length > 0
    ) {
      return { kind: "confirmed", provider, bookingId: confirmation.reference };
    }
    return { kind: "aborted", provider, classification: "invalid_provider_response" };
  } catch (error) {
    return classifyBeaconRejection(error, nowMs);
  }
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  record: StoredShipment,
  rejectionsForAbort: Rejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipment.id, record);
    return undefined;
  } catch {
    return emitAbort(
      dependencies,
      shipment.id,
      "repository",
      "repository_failure",
      rejectionsForAbort,
    );
  }
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    // Storage contains host-created queued records, starter dispatched records, or this service's JSON.
    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    let nextProvider: Provider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    const rejections: Rejection[] =
      shipment.state === "deferred" ? cloneRejections(shipment.rejections) : [];
    const request = providerRequest(shipment, command.recipient);

    for (let attempts = 0; attempts < 2; attempts += 1) {
      if (hasRefusal(rejections, nextProvider)) {
        return emitAbort(
          dependencies,
          shipment.id,
          nextProvider,
          "invalid_provider_response",
          rejections,
        );
      }

      const result = await attemptCarrier(dependencies, nextProvider, request, command.nowMs);
      if (result.kind === "confirmed") {
        const dispatched: DispatchedShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "dispatched",
          provider: result.provider,
          bookingId: result.bookingId,
          dispatchedAtMs: command.nowMs,
        };
        const saveFailure = await saveDecision(dependencies, shipment, dispatched, rejections);
        if (saveFailure) {
          return saveFailure;
        }
        dependencies.logger.info({
          shipmentId: shipment.id,
          action: "dispatched",
          provider: result.provider,
        });
        return { status: 200, body: publicShipment(dispatched) };
      }

      if (result.kind === "deferred") {
        const deferred: DeferredShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "deferred",
          nextProvider: result.provider,
          retryAtMs: result.retryAtMs,
          rejections: cloneRejections(rejections),
        };
        const saveFailure = await saveDecision(dependencies, shipment, deferred, rejections);
        if (saveFailure) {
          return saveFailure;
        }
        dependencies.logger.info({
          shipmentId: shipment.id,
          action: "deferred",
          provider: result.provider,
          retryAtMs: result.retryAtMs,
          rejections: cloneRejections(rejections),
        });
        return { status: 202, body: publicShipment(deferred) };
      }

      if (result.kind === "aborted") {
        return emitAbort(
          dependencies,
          shipment.id,
          result.provider,
          result.classification,
          rejections,
        );
      }

      rejections.push(result.rejection);
      if (result.rejection.provider === "atlas" && !hasRefusal(rejections, "beacon")) {
        nextProvider = "beacon";
        continue;
      }

      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "unavailable",
        rejections: cloneRejections(rejections),
      };
      const saveFailure = await saveDecision(dependencies, shipment, unavailable, rejections);
      if (saveFailure) {
        return saveFailure;
      }
      dependencies.logger.info({
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: cloneRejections(rejections),
      });
      return { status: 422, body: publicShipment(unavailable) };
    }

    return emitAbort(
      dependencies,
      shipment.id,
      nextProvider,
      "invalid_provider_response",
      rejections,
    );
  }

  return { handle };
}
